mapper.select:
select u.user_id,u.user_no, u.dept_id, u.nick_name, u.user_name, u.email, u.avatar, u.phonenumber, u.password, u.sex, u.status, u.del_flag, u.login_ip, u.login_date,u.create_by, u.create_time, u.remark, u.user_type,u.cert_entity_id, u.cert_id, u.buss_id, u.buss_name, u.eps_name,ifnull(d.tenant_id,-1) tenant_id,d2.dept_name tenant_name, d.dept_name, d.leader,u.image_id from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_dept d2 on d.tenant_id = d2.dept_id where u.del_flag = '0'
AND u.user_id = #{userId}
AND u.user_no = #{userNo}
AND u.user_name like concat('%', #{userName}, '%')
AND u.status = #{status}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND date_format(u.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')
AND date_format(u.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')
AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE find_in_set(#{deptId}, ancestors) ))
and u.user_type = #{userType} and u.cert_entity_id = #{certEntityId} and u.cert_id = #{certId} and u.buss_id = #{bussId} and u.buss_name like concat('%', #{bussName}, '%') and u.eps_name like concat('%', #{epsName}, '%') and d.tenant_id = #{tenantId}
and EXISTS (select 1 from sys_user_role t1,sys_role t2 where t2.del_flag = '0' and t2.role_id = t1.role_id and t1.user_id = u.user_id and t2.role_key = #{roleCode} )
and exists ( select 1 from sys_dept tb,sys_dept tb1 where tb.del_flag = '0' and tb.del_flag = '0' and tb1.dept_id = tb.parent_id and tb.dept_id = #{dataId} and tb1.dept_id = d.tenant_id )
and exists ( select 1 from sys_dept tb,sys_dept tb1 where tb.del_flag = '0' and tb.del_flag = '0' and tb1.dept_id = tb.parent_id and tb.dept_id = #{dataId} and tb1.dept_id = d.tenant_id ) AND EXISTS ( SELECT 1 FROM sys_user_role sr, sys_role r WHERE r.role_id = sr.role_id AND r.role_key = 'cgjl_manager' AND sr.user_id = u.user_id )
AND EXISTS ( SELECT 1 FROM sys_user_role sr, sys_role r WHERE r.role_id = sr.role_id AND r.role_key = 'cgjl_manager' AND sr.user_id = u.user_id )
AND u.nick_name LIKE CONCAT('%', #{queryNickName}, '%')
AND u.user_id != #{excludeId}

